async def act(page):
    """
    From the current New Product page state, perform the remaining actions necessary to:
    - Close the visible blocking popup (if present)
    - Open Prices tab and set Price = 169.99
    - Open Inventory tab and set Qty = 42 and Stock Availability = In Stock
    - Select Size = 34 and Color = Blue (if comboboxes exist)
    - Click Save as the final action

    All selectors use accessibility-tree-centric page.get_by_role calls and .select_option where appropriate.
    Save is the last action because it navigates away.
    """
    import asyncio

    async def _exists(locator):
        try:
            return await locator.count() > 0
        except Exception:
            return False

    async def _try_fill(pairs, value):
        for role, name in pairs:
            try:
                loc = page.get_by_role(role, name=name)
                if await _exists(loc):
                    await loc.fill(value)
                    return True
            except Exception:
                pass
        # fallbacks
        try:
            sp = page.get_by_role("spinbutton")
            if await _exists(sp.nth(0)):
                await sp.nth(0).fill(value)
                return True
        except Exception:
            pass
        try:
            tb = page.get_by_role("textbox")
            if await _exists(tb.nth(0)):
                await tb.nth(0).fill(value)
                return True
        except Exception:
            pass
        return False

    async def _try_select(pairs, option_label):
        for role, name in pairs:
            try:
                loc = page.get_by_role(role, name=name)
                if await _exists(loc):
                    try:
                        await loc.select_option({"label": option_label})
                    except Exception:
                        try:
                            await loc.select_option(option_label)
                        except Exception:
                            try:
                                await loc.click()
                            except Exception:
                                pass
                    return True
            except Exception:
                pass
        # fallback: any combobox on page
        try:
            cb = page.get_by_role("combobox")
            if await _exists(cb.nth(0)):
                try:
                    await cb.nth(0).select_option({"label": option_label})
                except Exception:
                    await cb.nth(0).select_option(option_label)
                return True
        except Exception:
            pass
        return False

    async def _try_check_checkbox(pairs, desired=True):
        for role, name in pairs:
            try:
                loc = page.get_by_role(role, name=name)
                if await _exists(loc):
                    if desired:
                        await loc.check()
                    else:
                        await loc.uncheck()
                    return True
            except Exception:
                pass
        return False

    # 1) Attempt to close blocking popup/dialog if present.
    # Try dialog role first, then common-named close buttons, finally Escape.
    try:
        dialogs = page.get_by_role("dialog")
        if await _exists(dialogs):
            # click a button inside the dialog if present
            try:
                btns = dialogs.get_by_role("button")
                if await _exists(btns):
                    await btns.first.click()
                    await asyncio.sleep(0.35)
            except Exception:
                try:
                    await page.keyboard.press("Escape")
                    await asyncio.sleep(0.35)
                except Exception:
                    pass
        else:
            closed = False
            for name in ["×", "Close", "close", "OK", "Dismiss"]:
                try:
                    b = page.get_by_role("button", name=name)
                    if await _exists(b):
                        await b.click()
                        await asyncio.sleep(0.35)
                        closed = True
                        break
                except Exception:
                    pass
            if not closed:
                try:
                    await page.keyboard.press("Escape")
                    await asyncio.sleep(0.35)
                except Exception:
                    pass
    except Exception:
        # continue even if modal handling errors
        pass

    # small stabilization pause
    await asyncio.sleep(0.25)

    # 2) Open Prices tab and set Price = 169.99
    try:
        prices_link = page.get_by_role("link", name="Prices")
        if await _exists(prices_link):
            await prices_link.click()
            await page.wait_for_load_state("networkidle")
            await asyncio.sleep(0.25)
    except Exception:
        pass

    await _try_fill([
        ("spinbutton", "Price"),
        ("textbox", "Price"),
        ("spinbutton", "Price *"),
        ("textbox", "Price *")
    ], '169.99')

    # 3) Open Inventory tab and set Qty = 42 and Stock Availability = In Stock
    try:
        inventory_link = page.get_by_role("link", name="Inventory")
        if await _exists(inventory_link):
            await inventory_link.click()
            await page.wait_for_load_state("networkidle")
            await asyncio.sleep(0.25)
    except Exception:
        pass

    await _try_fill([
        ("spinbutton", "Qty"),
        ("textbox", "Qty"),
        ("textbox", "Quantity")
    ], '42')

    await _try_select([
        ("combobox", "Stock Availability"),
        ("combobox", "is_in_stock"),
        ("combobox", "Stock Status")
    ], 'In Stock')

    # also try checkbox styles
    await _try_check_checkbox([
        ("checkbox", "Is In Stock"),
        ("checkbox", "is_in_stock")
    ], desired=True)

    await asyncio.sleep(0.2)

    # 4) Attempt to set attributes Size=34 and Color=Blue (try current view then General tab)
    await _try_select([("combobox", "Size"), ("combobox", "Size *")], '34')
    await _try_select([("combobox", "Color"), ("combobox", "Color *")], 'Blue')

    try:
        general_link = page.get_by_role("link", name="General")
        if await _exists(general_link):
            await general_link.click()
            await page.wait_for_load_state("networkidle")
            await asyncio.sleep(0.25)
            await _try_select([("combobox", "Size"), ("combobox", "Size *")], '34')
            await _try_select([("combobox", "Color"), ("combobox", "Color *")], 'Blue')
    except Exception:
        pass

    await asyncio.sleep(0.2)

    # 5) Click Save (final action). Must be the last action.
    save_btn = page.get_by_role("button", name="Save")
    if await _exists(save_btn):
        try:
            await save_btn.scroll_into_view_if_needed()
        except Exception:
            pass
        await save_btn.click()
        return

    # fallback save variants
    for alt in ["Save and Continue Edit", "Save Product", "Save Item"]:
        try:
            b = page.get_by_role("button", name=alt)
            if await _exists(b):
                try:
                    await b.scroll_into_view_if_needed()
                except Exception:
                    pass
                await b.click()
                return
        except Exception:
            pass

    raise RuntimeError('Unable to locate the Save button to complete product creation')
